<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require dirname(__DIR__).'/vendor/autoload.php';
use ReGen\{AdminAccess,AdminRepository,Config,ConcurrentUpdate,MaintenanceService,RealtimeEvents,ResumeRepository,TemplateManagement,UserRepository};
Config::load(dirname(__DIR__));
if(!in_array(Config::get('app.env'),['development','test','testing'],true)||!in_array(Config::get('db.host'),['localhost','127.0.0.1','::1'],true))throw new RuntimeException('Local development database required.');
$connect=static fn(?string $name=null):PDO=>new PDO('mysql:host='.Config::get('db.host').';port='.Config::get('db.port').($name?';dbname='.$name:'').';charset=utf8mb4',Config::get('db.user'),Config::get('db.password'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
$server=$connect();$name='regen_live_test_'.bin2hex(random_bytes(6));$server->exec('CREATE DATABASE `'.$name.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$count=0;
$check=static function(bool $ok,string $message)use(&$count):void{$count++;if(!$ok)throw new RuntimeException($message);};
$reject=static function(callable $call,string $message)use($check):void{try{$call();}catch(DomainException|OutOfBoundsException|ConcurrentUpdate){$check(true,$message);return;}$check(false,$message);};
try{
    $db=$connect($name);$db->exec(file_get_contents(dirname(__DIR__).'/database/schema.sql'));$db->exec("UPDATE feature_prices SET mode='free',token_cost=0 WHERE feature_key='templates'");
    $users=new UserRepository($db);$one=$users->create(['firstName'=>'First','lastName'=>'Person','email'=>'first@fixture.regen.local','password'=>'Fixture-Password-567890']);$two=$users->create(['firstName'=>'Second','lastName'=>'Person','email'=>'second@fixture.regen.local','password'=>'Fixture-Password-567890']);
    $uid=(int)$one['id'];$other=(int)$two['id'];$events=new RealtimeEvents($db);
    $person=['role'=>'user','id'=>$uid,'topics'=>['notifications','support','maintenance']];
    $events->publish('notifications','user',$uid);$events->publish('notifications','user',$other);$events->publish('support','admin',0,123);$events->publish('maintenance','users');$events->dispatch();
    $data=$events->read($person,0);$check(count($data['events'])===2,'Private events must exclude other users and administrators.');
    $check(array_column($data['events'],'topic')===['notifications','maintenance'],'Only authorized topics are delivered.');
    $check($events->read(['role'=>'admin','id'=>1,'topics'=>['templates']],0)['events']===[],'Delegated administrator topic filters must be enforced by the server.');
    $check(count($events->read(['role'=>'admin','id'=>1,'topics'=>['support']],0)['events'])===1,'Authorized admin channel must receive its event.');
    $check($events->read($person,$data['cursor'])['events']===[],'Replaying a checkpoint must not repeat already consumed events.');
    $check($events->read($person,PHP_INT_MAX)['reset'],'Forged future cursors request reconciliation.');
    $before=$events->cursor();$db->beginTransaction();$events->publish('support','user',$uid);$db->rollBack();$events->dispatch();$check($events->cursor()===$before,'Rolled-back mutations must never generate events.');
    $second=$connect($name);$secondEvents=new RealtimeEvents($second);
    $db->beginTransaction();$events->publish('support','user',$uid,41);
    $secondEvents->publish('support','user',$uid,42);$secondEvents->dispatch();$middle=$secondEvents->read($person,$before);
    $check(array_column($middle['events'],'resourceId')===[42],'An uncommitted event must remain invisible.');
    $db->commit();$events->dispatch();$late=$events->read($person,$middle['cursor']);
    $check(array_column($late['events'],'resourceId')===[41],'Replay must retain a later commit with a lower outbox ID.');
    $check(!method_exists(ReGen\RealtimeConnection::class,'acquire'),'Update delivery must not acquire long-lived PHP worker leases.');
    $check(!str_contains(file_get_contents(dirname(__DIR__).'/php/src/RealtimeConnection.php'),'usleep('),'Delta delivery must not wait inside a PHP request.');
    $admins=new AdminRepository($db);$super=$admins->findByEmail('admin@regen.com');$admin=(int)$super['id'];
    $maintenance=new MaintenanceService($db);$check(!$maintenance->status()['active'],'Maintenance starts disabled.');
    $now=time();$config=['mode'=>'scheduled','title'=>'ReGen is being improved.','message'=>'Your saved work will be available when maintenance ends.','startsAt'=>gmdate('Y-m-d\TH:i:s\Z',$now+60),'endsAt'=>gmdate('Y-m-d\TH:i:s\Z',$now+120),'estimatedAt'=>gmdate('Y-m-d\TH:i:s\Z',$now+100),'version'=>0];
    $maintenance->save($config,$admin);$check($maintenance->status($now)['state']==='scheduled','Future maintenance must remain scheduled.');
    $check($maintenance->status($now+61)['active'],'Scheduled maintenance activates without a browser or worker.');
    $check($maintenance->status($now+120)['state']==='completed'&&!$maintenance->status($now+121)['active'],'End time restores access automatically.');
    $reject(fn()=>$maintenance->save($config,$admin),'Concurrent administrators must not overwrite a maintenance revision.');
    $reject(fn()=>$maintenance->save(array_replace($config,['version'=>1,'endsAt'=>$config['startsAt']]),$admin),'Contradictory dates must be rejected.');
    $reject(fn()=>$maintenance->save(array_replace($config,['version'=>1,'startsAt'=>'2026-02-30T12:00:00Z']),$admin),'Invalid calendar dates must be rejected.');
    $immediate=array_replace($config,['mode'=>'immediate','startsAt'=>null,'endsAt'=>null,'estimatedAt'=>null,'version'=>1]);$maintenance->save($immediate,$admin);$check($maintenance->status()['active'],'Immediate maintenance allows an indefinite period.');
    $maintenance->save(array_replace($immediate,['mode'=>'off','version'=>2]),$admin);$check(!$maintenance->status()['active'],'Authorized disabling restores normal access.');
    $access=new AdminAccess($db);$delegate=$admins->createAdmin(['firstName'=>'Template','lastName'=>'Editor','email'=>'editor@fixture.regen.local','password'=>'Fixture-Password-567890','role'=>'admin']);
    $access->assign($delegate,['capabilities'=>['templates.view','templates.manage'],'purpose'=>'Manage the public design collection.','version'=>0],$admin);
    $actor=$admins->findById($delegate);$route='/api/admin/templates/classic/resumes';
    $check(!$access->allows($actor,$route,'GET'),'Template management alone must not grant private resume access.');
    $access->assign($delegate,['capabilities'=>['templates.view','templates.resumes'],'purpose'=>'Investigate saved resume layout issues.','version'=>1],$admin);
    $check($access->allows($actor,$route,'GET'),'A separately granted private-resume read permission enables viewing.');
    $check(!$access->allows($actor,$route,'POST'),'Private resume viewing must remain read only.');
    $resume=(new ResumeRepository($db))->getOrCreatePrimary($uid,$one,'First saved resume');$catalog=new TemplateManagement($db);
    $usage=$catalog->usage('classic');$check($usage['total']===1&&count($usage['items'])===1,'Usage must count real saved resume records.');
    $check($catalog->savedResume('classic',(int)$resume['id'])['userId']===$uid,'Viewer must select the actual saved resume owner.');
    $reject(fn()=>$catalog->savedResume('modern',(int)$resume['id']),'Changing the template in a private viewer URL must fail.');
    $check($catalog->usage('classic',1,'does-not-match')['total']===0,'Usage search must filter the real records.');
    $check((new ResumeRepository($db))->getById((int)$resume['id'],$other)===null,'Normal users cannot access another person’s resume.');
    $check(!str_contains(json_encode($events->read($person,0)),'email')&&!str_contains(json_encode($events->read($person,0)),'resumeData'),'Live events must carry no private document or account content.');
    $previousSession=$_SESSION??[];$previousPath=$_SERVER['REQUEST_URI']??'/';$previousMethod=$_SERVER['REQUEST_METHOD']??'GET';
    $_SESSION=['adminId'=>$admin,'loginAt'=>time(),'lastActivityAt'=>time()-100,'lastRotationAt'=>time()-1000];$last=$_SESSION['lastActivityAt'];$_SERVER['REQUEST_METHOD']='GET';
    $refresh=new ReflectionMethod(ReGen\Session::class,'refreshLifecycle');
    $_SERVER['REQUEST_URI']='/api/realtime/events';$refresh->invoke(null,$db);$check($_SESSION['lastActivityAt']===$last,'Event streams must not renew administrator idle activity.');
    $_SERVER['REQUEST_URI']='/api/admin/alerts';$refresh->invoke(null,$db);$check($_SESSION['lastActivityAt']===$last,'Automatic admin reads must not renew idle activity either.');
    $_SESSION=$previousSession;$_SERVER['REQUEST_URI']=$previousPath;$_SERVER['REQUEST_METHOD']=$previousMethod;
    echo "Live event isolation, transaction ordering, replay, maintenance schedules and private resume permissions passed ($count assertions; isolated database).\n";
}finally{if($db->inTransaction())$db->rollBack();$server->exec('DROP DATABASE `'.$name.'`');}
